--
-- Name: v_parish_summary; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.v_parish_summary AS
 SELECT run_id,
    COALESCE(parish_name, '(unassigned)'::text) AS parish_name,
    count(*) AS n_sites,
    round(((sum(area_m2) / (10000.0)::double precision))::numeric, 2) AS total_ha,
    round(((max(area_m2) / (10000.0)::double precision))::numeric, 2) AS largest_ha
   FROM analysis.site
  WHERE in_urban_plan
  GROUP BY run_id, COALESCE(parish_name, '(unassigned)'::text);


--
-- Name: v_site_ranked; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.v_site_ranked AS
 SELECT site_id,
    run_id,
    geom,
    area_m2,
    score_mean,
    score_max,
    in_urban_plan,
    parish_name,
    round(((area_m2 / (10000.0)::double precision))::numeric, 2) AS area_ha,
        CASE
            WHEN in_urban_plan THEN rank() OVER (PARTITION BY run_id, in_urban_plan ORDER BY area_m2 DESC)
            ELSE NULL::bigint
        END AS rank_by_area
   FROM analysis.site s;


